<li>플랍에서 내 앞사람이 벳 10, 그 다음 사람이 레이즈 30. 내가 할 수 있는 행동은? → <b>폴드, 콜(30), 레이즈(최소 50)</b>. 증가분이 20이니 최소 레이즈는 50.</li>
